public static double CircularInterpolation(double x0, double y0, double x1, double y1) {
    // Calculate the center point and radius
    double x = x0 + (x1 - x0) / 2;
    double y = y0 + (y1 - y0) / 2;

    // Calculate the distance between the centers
    double distance = Math.Sqrt((x1 - x0)^2 + (y1 - y0)^2);

    // Calculate the interpolated value
    return Math.Abs(distance * Math.PI / 4);
}
